$r=gm_assessment_summary($record,['journals'=>[$mixed]],'2026-10-17');zp_check($r['controlLedger']['assessmentRecorded']&&$r['controlLedger']['annualDebitPKR']===250.0,'A later payment allocation hold cannot erase the completed annual assessment debit');zp_check(!$r['progress']['complete']&&$r['paymentWarnings']&&$r['paidPKR']===0.0,'Ambiguous cash cannot mark the annual payment reconciliation complete');
